steps.script:
$ErrorActionPreference='Stop'
$o=@{action='deploy_private_v2_only';state='started';secrets_untouched=$true;other_workers_untouched=$true}
try {
 $dir=Join-Path $env:TEMP 'ttactualidad-v2-private'
 if(!(Test-Path -LiteralPath (Join-Path $dir '.git'))){throw 'REPO_MISSING'}
 Push-Location $dir
 try {
  $branch=(& git branch --show-current | Out-String).Trim()
  if($branch -ne 'feature/ttactualidad-v2-private-worker-20261114'){throw 'WRONG_BRANCH'}
  $log=Join-Path $env:TEMP 'tt-v2-private-pull-bridge.log'
  & cmd.exe /d /c "git pull --ff-only origin feature/ttactualidad-v2-private-worker-20261114 1> \"$log\" 2>&1"
  if($LASTEXITCODE -ne 0){throw 'GIT_PULL_FAILED'}
  $head=(& git rev-parse HEAD | Out-String).Trim()
  if($head -ne '47beb8fd58d84e585ccf923cfd578de3b6a1704d'){throw 'HEAD_NOT_VALIDATED'}
  Set-Location (Join-Path $dir 'v2\private-worker')
  $cfg=Get-Content -LiteralPath '.\wrangler.jsonc' -Raw
  if(!$cfg.Contains('"name": "ttactualidad-v2-private-test"')){throw 'WORKER_MISMATCH'}
  $buildLog=Join-Path $env:TEMP 'tt-v2-private-build-bridge.log'
  & cmd.exe /d /c "npm.cmd run build 1> \"$buildLog\" 2>&1"
  if($LASTEXITCODE -ne 0){throw 'BUILD_FAILED'}
  if(!(Select-String -LiteralPath $buildLog -Pattern 'TT_V2_PRIVATE_BUILD_READY=YES' -Quiet)){throw 'BUILD_NOT_VERIFIED'}
  $bundle=Get-Content -LiteralPath '.\dist\app.js' -Raw
  if(!$bundle.Contains('Radar · ') -or !$bundle.Contains('ttactualidad.rainyraven22.chatgpt.site') -or !$bundle.Contains('pilot/jordi-wild.webp')){throw 'BUNDLE_INCOMPLETE'}
  $deployLog=Join-Path $env:TEMP 'tt-v2-private-deploy-bridge.log'
  & cmd.exe /d /c "npx.cmd wrangler deploy --keep-vars 1> \"$deployLog\" 2>&1"
  if($LASTEXITCODE -ne 0){throw 'DEPLOY_FAILED'}
  if(!(Select-String -LiteralPath $deployLog -Pattern 'Deployed ttactualidad-v2-private-test triggers' -Quiet)){throw 'DEPLOY_UNCONFIRMED'}
  $o.state='deployed';$o.revision=$head;$o.url='https://ttactualidad-v2-private-test.fabricelop.workers.dev'
 } finally {Pop-Location}
}catch {$o.state='failed';$o.error_class=$_.Exception.Message}
Write-Output ('TTRESULT:'+($o|ConvertTo-Json -Compress))
